import { handleMiddleware } from "@opennextjs/aws/core/routing/middleware.js";
import type { InternalEvent } from "@opennextjs/aws/types/open-next.js";
import { vi } from "vitest";

// Matchers generated by Next.js 16.4.5 for `["/admin/:path*", "/api/:path*"]` with i18n.
// The locales are the ones of the Next.js i18n documentation.
vi.mock("@opennextjs/aws/adapters/config/index.js", () => ({
  NextConfig: {
    i18n: {
      defaultLocale: "en-US",
      locales: ["en-US", "fr", "nl-NL"],
    },
  },
  MiddlewareManifest: {
    sortedMiddleware: ["/"],
    middleware: {
      "/": {
        files: [],
        name: "middleware",
        page: "/",
        matchers: [
          {
            regexp:
              "^(?:\\/(_next\\/data\\/[^/]{1,}))?(?:\\/((?!_next\\/)[^/.]{1,}))\\/admin(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/admin/:path*",
          },
          {
            regexp:
              "^(?:\\/(_next\\/data\\/[^/]{1,}))?(?:\\/((?!_next\\/)[^/.]{1,}))\\/api(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/api/:path*",
          },
          // A matcher with `locale: false` has no locale group, the locale is part of its source.
          {
            regexp:
              "^(?:\\/(_next\\/data\\/[^/]{1,}))?\\/en-US\\/reports(?:\\/((?:[^\\/#\\?]+?)(?:\\/(?:[^\\/#\\?]+?))*))?(\\.json|\\.rsc|\\.segments\\/.+\\.segment\\.rsc)?[\\/#\\?]?$",
            originalSource: "/en-US/reports/:path*",
          },
        ],
      },
    },
    functions: {},
    version: 2,
  },
  FunctionsConfigManifest: undefined,
  PrerenderManifest: {
    preview: {
      previewModeId: "preview",
    },
  },
}));

function createEvent(
  rawPath: string,
  cookies: Record<string, string> = {},
): InternalEvent {
  return {
    type: "core",
    method: "GET",
    rawPath,
    url: `https://example.com${rawPath}`,
    body: Buffer.from(""),
    headers: {},
    query: {},
    cookies,
    remoteAddress: "::1",
  };
}

describe("handleMiddleware with mixed case locales", () => {
  it.each([
    ["/admin", "/en-US/admin"],
    ["/en-US/admin", "/en-US/admin"],
    ["/en-us/admin", "/en-us/admin"],
    ["/EN-US/admin/users", "/EN-US/admin/users"],
    ["/nl-NL/admin", "/nl-NL/admin"],
    ["/fr/admin", "/fr/admin"],
    ["/en-US/api/users", "/en-US/api/users"],
  ])("runs the middleware for %s", async (rawPath, middlewarePath) => {
    const middleware = vi
      .fn()
      .mockResolvedValue(new Response("auth required", { status: 401 }));
    const middlewareLoader = vi.fn().mockResolvedValue({ default: middleware });

    const result = await handleMiddleware(
      createEvent(rawPath),
      "",
      middlewareLoader,
    );

    expect(middleware).toHaveBeenCalledWith(
      expect.objectContaining({
        url: `https://example.com${middlewarePath}`,
      }),
    );
    expect(result).toEqual(expect.objectContaining({ statusCode: 401 }));
  });
});

describe("handleMiddleware with a matcher for the default locale", () => {
  it.each<Record<string, string>>([
    {},
    { NEXT_LOCALE: "fr" },
    { NEXT_LOCALE: "nl-nl" },
  ])(
    "runs the middleware for /reports with the cookies %o",
    async (cookies) => {
      const middleware = vi
        .fn()
        .mockResolvedValue(new Response("auth required", { status: 401 }));
      const middlewareLoader = vi
        .fn()
        .mockResolvedValue({ default: middleware });

      const result = await handleMiddleware(
        createEvent("/reports", cookies),
        "",
        middlewareLoader,
      );

      expect(middleware).toHaveBeenCalledOnce();
      expect(result).toEqual(expect.objectContaining({ statusCode: 401 }));
    },
  );

  it("does not run the middleware for another locale", async () => {
    const middlewareLoader = vi.fn();
    const event = createEvent("/fr/reports");

    const result = await handleMiddleware(event, "", middlewareLoader);

    expect(middlewareLoader).not.toHaveBeenCalled();
    expect(result).toBe(event);
  });
});
